import sys, io, glob, os
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
from docx import Document
import re
pats = re.compile(r"(CET|四级|六级|普通话|分数|500)")
for path in glob.glob("**/*.docx", recursive=True) + glob.glob("*.txt") + glob.glob("*.md"):
    if os.path.basename(path).startswith("~$"): continue
    try:
        if path.endswith(".docx"):
            d = Document(path)
            texts = [p.text for p in d.paragraphs]
            for t in d.tables:
                for r in t.rows:
                    for c in r.cells:
                        texts += [x.text for x in c.paragraphs]
        else:
            texts = open(path, encoding="utf-8", errors="ignore").read().splitlines()
    except Exception as e:
        continue
    for t in texts:
        if pats.search(t or ""):
            print("%-60s | %s" % (os.path.basename(path)[:58], t.strip()[:110]))
