import sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8")
from docx import Document
from docx.oxml.ns import qn
EMU=12700
d = Document("UserX_简历_一微科技_机器人研发实习生.docx")
def eff(p, tag):
    # walk pPr/rPr sz, fall back to Normal style, then docDefaults
    pr = p._p.find(qn('w:pPr'))
    sz=None
    if pr is not None:
        rpr = pr.find(qn('w:rPr'))
        if rpr is not None:
            s = rpr.find(qn('w:sz'))
            if s is not None: sz = int(s.get(qn('w:val')))/2
    # run level
    runsz=set()
    for r in p.runs:
        rpr = r._element.find(qn('w:rPr'))
        if rpr is not None:
            s = rpr.find(qn('w:sz'))
            if s is not None: runsz.add(int(s.get(qn('w:val')))/2)
    print("%-8s pPr_sz=%s run_sz=%s | %s" % (tag, sz, sorted(runsz), p.text[:45]))
t = d.tables[0]
c0, c1 = t.rows[0].cells
print("=== LEFT sidebar ===")
for i,p in enumerate(c0.paragraphs):
    if p.text.strip(): eff(p, "L%d"%i)
print("=== RIGHT main ===")
for i,p in enumerate(c1.paragraphs):
    if p.text.strip(): eff(p, "R%d"%i)
