{"content": "# -*- coding: utf-8 -*-
import sys, fitz

NAVY = (0.145, 0.275, 0.396)

def check(path, label):
    doc = fitz.open(path)
    n = len(doc)
    page = doc[0]
    H = page.rect.height
    blocks = page.get_text("dict")["blocks"]
    main_bottom = 0
    for b in blocks:
        if b.get("type") != 0:
            continue
        if b["bbox"][0] >= 190:
            main_bottom = max(main_bottom, b["bbox"][3])
    fill = main_bottom / H * 100

    # navy panel bottom
    panel_bottom = 0
    for d in page.get_drawings():
        if d.get("fill") is None:
            continue
        r, g, bl = d["fill"]
        if abs(r - NAVY[0]) < 0.03 and abs(g - NAVY[1]) < 0.03 and abs(bl - NAVY[2]) < 0.03:
            x0, y0, x1, y1 = d["rect"]
            if x0 < 60 and (x1 - x0) > 80 and (y1 - y0) > 200:
                panel_bottom = max(panel_bottom, y1)
    gap = H - panel_bottom

    # sidebar wrapping: lines starting at sidebar x, x1 >= 177.4 and short
    lines = []
    for b in blocks:
        if b.get("type") != 0:
            continue
        for l in b.get("lines", []):
            x0, y0, x1, y1 = l["bbox"]
            if x1 < 195:
                txt = "".join(s["text"] for s in l["spans"])
                lines.append((round(x0, 1), round(y1, 1), round(x1, 1), txt))
    lines.sort(key=lambda t: t[1])
    wrap = []
    for i, (x0, y1, x1, txt) in enumerate(lines):
        if x1 >= 177.4 and i + 1 < len(lines):
            nx0, ny1, nx1, ntxt = lines[i + 1]
            if abs(nx0 - x0) < 1.5 and len(ntxt.strip()) <= 12:
                wrap.append((txt, ntxt))

    print(f"{label}: pages={n} fill={fill:.1f}% gap={gap:.1f}pt wrap={len(wrap)}")
    for w in wrap:
        print("   WRAP:", w)

for p, lab in [(sys.argv[1], "设备ME"), (sys.argv[2], "机械结构")]:
    check(p, lab)
